USE [master];SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @R varchar(20)='$(RunToken)',@T sysname=N'$(TargetDatabase)',@S nvarchar(max),@L sysname,@C int=CASE TRY_CONVERT(int,SERVERPROPERTY('ProductMajorVersion')) WHEN 15 THEN 150 WHEN 16 THEN 160 WHEN 17 THEN 170 END;IF '$(DemoId)'<>'STL-008' OR @T<>N'SQLPERF_LAB_STL008_'+@R OR @C IS NULL THROW 51000,'FAIL_CONTRACT: STL-008-Setupziel ist ungueltig.',1;IF DB_ID(@T) IS NOT NULL THROW 51002,'FAIL_STATE: STL-008-Zieldatenbank existiert.',1;SET @S=N'CREATE DATABASE '+QUOTENAME(@T)+N';ALTER DATABASE '+QUOTENAME(@T)+N' SET RECOVERY SIMPLE;ALTER DATABASE '+QUOTENAME(@T)+N' SET COMPATIBILITY_LEVEL='+CONVERT(nvarchar(3),@C)+N';';EXEC(@S);SELECT @L=name FROM sys.master_files WHERE database_id=DB_ID(@T) AND type=1;SET @S=N'ALTER DATABASE '+QUOTENAME(@T)+N' MODIFY FILE(NAME='+QUOTENAME(@L,N'''')+N',FILEGROWTH=1MB);';EXEC(@S);SET @S=N'USE '+QUOTENAME(@T)+N';EXEC sys.sp_addextendedproperty @name=N''SQLPERF.Project'',@value=N''SQL_PerformanceSchulung'';EXEC sys.sp_addextendedproperty @name=N''SQLPERF.ContractVersion'',@value=N''1.0'';EXEC sys.sp_addextendedproperty @name=N''SQLPERF.DemoId'',@value=N''STL-008'';EXEC sys.sp_addextendedproperty @name=N''SQLPERF.RunToken'',@value=@R;';EXEC sys.sp_executesql @S,N'@R varchar(20)',@R=@R;
GO
USE [$(TargetDatabase)];IF SCHEMA_ID(N'lab') IS NULL EXEC(N'CREATE SCHEMA lab AUTHORIZATION dbo;');CREATE TABLE lab.LogLoad(RowId int IDENTITY PRIMARY KEY,Payload varchar(4000) NOT NULL);CREATE TABLE lab.Evidence(Stage varchar(16) PRIMARY KEY,VlfCount int NOT NULL,LogSizeMB decimal(19,2) NOT NULL,GrowthMB decimal(19,2) NOT NULL);PRINT 'SQLPERF_SUMMARY|PASS|OK';
